import { EmptyState } from "@/components/common";
import { HistoryRow, type HistoryMessage } from "./HistoryRow";
import type { ShortlistState } from "./RowActions";
import styles from "./history.module.css";
export function HistoryTable({
  messages,
  filtered,
  shortlistStates,
}: {
  messages: HistoryMessage[];
  filtered: boolean;
  shortlistStates: Record<string, ShortlistState>;
}) {
  return (
    <section
      className={`hover-card backdrop-blur-xs [border:1px_solid_var(--h-border)] rounded-[var(--appearance-radius,_22px)] [background:var(--h-surface)] overflow-hidden`}
      aria-label="Delivery history table"
    >
      <table
        className={`${styles.table} min-w-0 block w-full text-[14px]`}
        role="table"
      >
        <caption className="sr-only">Email delivery history</caption>
        <thead role="rowgroup">
          <tr
            className={`${styles.row} grid grid-cols-[minmax(0,_2.2fr)_minmax(0,_1.9fr)_minmax(0,_1.1fr)_minmax(0,_1fr)_minmax(0,_1.1fr)_84px] items-center gap-3.5 py-3.5 px-5 [@media(max-width:_859px)]:grid-cols-[minmax(0,_1fr)_84px] [@media(max-width:_859px)]:gap-y-2.5 ${styles.heading} [border-top:0] [font:500_11px_var(--font-jetbrains),_monospace] uppercase tracking-[0.1em] text-[var(--h-muted)] pt-4`}
            role="row"
          >
            {[
              "Recipient",
              "Role · Company",
              "Template",
              "Sent",
              "Status",
              "Actions",
            ].map((label) => (
              <th
                role="columnheader"
                scope="col"
                key={label}
                style={label === "Actions" ? { textAlign: "right" } : undefined}
              >
                {label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody role="rowgroup">
          {messages.length ? (
            messages.map((message) => (
              <HistoryRow
                key={message.id}
                message={message}
                shortlist={shortlistStates[message.contactId]}
              />
            ))
          ) : (
            <tr
              className={`${styles.empty} block py-11 px-5 text-center text-[var(--h-muted)]`}
            >
              <td colSpan={6}>
                {filtered ? (
                  "No messages match. Try a different search or status."
                ) : (
                  <EmptyState
                    title="Your introductions start here"
                    description="Once you send a campaign, each recipient’s submission and manually marked replies will appear here."
                    href="/compose"
                    link="Compose an Email"
                  />
                )}
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </section>
  );
}
